/* Reduce Motion: part instant, object instant, hinge instant, surface crossfade, settle crossfade, chrome crossfade, release unchanged, refusal instant. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --mu-travel-part: 0;
    --mu-spring-part-d: 0s;
    --mu-travel-object: 0;
    --mu-spring-object-d: 0s;
    --mu-travel-hinge: 0;
    --mu-spring-hinge-d: 0s;
    --mu-travel-surface: 0;
    --mu-travel-settle: 0;
    --mu-travel-chrome: 0;
    --mu-travel-refusal: 0;
    --mu-spring-refusal-d: 0s;
  }
}
